CREATE SCHEMA IF NOT EXISTS messaging;

CREATE TABLE IF NOT EXISTS messaging.mail_activity_types (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    summary TEXT,
    note TEXT,
    category mail_activity_category,
    chaining_type mail_activity_chaining_type NOT NULL DEFAULT 'suggest',
    delay_count INTEGER NOT NULL DEFAULT 0,
    delay_unit mail_activity_delay_unit NOT NULL DEFAULT 'days',
    delay_from mail_activity_delay_from NOT NULL DEFAULT 'previous_activity',
    default_user_id UUID,
    default_note TEXT,
    icon TEXT,
    res_model TEXT,
    res_model_id UUID,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

